import{z as s,x as i,o as r,c as p,q as o,j as t,D as e,d as n,s as A,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"高管薪酬与激励","description":"","frontmatter":{"title":"高管薪酬与激励","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/executive-compensation.md","filePath":"econ/executive-compensation.md","lastUpdated":1791063341000}'),d={name:"econ/executive-compensation.md"};function m(c,a,h,u,C,F){const B=i("Mermaid");return r(),p("div",null,[a[2]||(a[2]=o('<h1 id="高管薪酬与激励" tabindex="-1">高管薪酬与激励 <a class="header-anchor" href="#高管薪酬与激励" aria-label="Permalink to &quot;高管薪酬与激励&quot;">​</a></h1><div class="epigraph"><p>薪酬应让经理分担不可分散的企业风险，以换努力与少偷懒；可验证的业绩度量会被操纵，最优合同是激励、风险分担与度量扭曲之间的权衡。</p><footer>—— Jensen and Murphy, Performance Pay and Top-Management Incentives, Journal of Political Economy 1990；Holmström, Moral Hazard and Observability, Bell Journal of Economics 1979；对照 Tirole 第 1 编</footer></div><p><a href="/econ/boards-monitoring">上一课</a>给出谁设计合同。本课缺口是合同内容：股权、期权、奖金如何对接<a href="/econ/moral-hazard">道德风险</a>与<a href="/econ/multitask-holmstrom">多任务</a>，以及 Jensen–Murphy 的「薪酬–业绩敏感度为何看起来低」。不重推一阶方法，不把期权会计当主体。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经理努力不可验证，结果有噪音。Holmström：最优是把薪酬连到信息量高的信号（充足统计）。Jensen–Murphy：美国 CEO 的财富对股东价值的敏感度在样本里很小，像激励不足；反驳是风险厌恶、度量差、以及董事会被俘获后的抽租（Bebchuk–Fried）。缺口是：治理进阶把薪酬写成激励合同，而不是人力资源价目表。Tirole：有限责任与参与约束使高能激励变贵，低敏感度可以是最优而不是丑闻。</p><p><span class="marginnote">多任务：可度量的（股价、会计）挤出不可度量的（维护、安全、长期客户）。Holmström–Milgrom：任务间激励必须平衡，否则高能激励有害。EVA 课已警告单期会计。</span></p><p><span class="marginnote">充足统计直译是「信息够用就行」：薪酬只应挂在业绩中真正反映经理努力的那部分上。比如公司涨了 8%，而同行业平均涨了 6%，多出来的 2% 才可能归功于经理；随大盘涨的那 6% 是共同噪音，把它剔除（相对绩效）能让经理少白担风险、公司少付激励溢价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具：工资（保险）、奖金（会计）、股票与期权（市值）、解雇威胁（董事会）、职业关注（<a href="/econ/career-concerns">career-concerns</a>）。相对绩效：滤掉市场噪音，但会惩罚行业共同冲击下的正确行动，也可能鼓励破坏对手。期权：凸性鼓励风险承担，靠近债的资产替代——杠杆企业给虚值期权会加重赌大。</p><p>董事会俘获：经理影响薪酬委员会，合同变成租金抽取，用激励作包装。检验方向：差治理与高薪酬、低敏感度并存。本课并列激励最优与抽租，不裁判哪一篇回归赢。</p>',10)),(r(),t(l,null,{default:e(()=>[A(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MH%5B%22%E5%8A%AA%E5%8A%9B%E4%B8%8D%E5%8F%AF%E8%A7%81%22%5D%20--%3E%20PAY%5B%22%E8%96%AA%E9%85%AC%E8%BF%9E%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20NOISE%5B%22%E5%99%AA%E9%9F%B3%20%2F%20%E9%A3%8E%E9%99%A9%E5%8E%8C%E6%81%B6%22%5D%20--%3E%20LOW%5B%22%E6%95%8F%E6%84%9F%E5%BA%A6%E4%B8%8D%E5%BF%85%E9%AB%98%22%5D%0A%20%20MEAS%5B%22%E5%BA%A6%E9%87%8F%E6%89%AD%E6%9B%B2%22%5D%20--%3E%20MULTI%5B%22%E5%A4%9A%E4%BB%BB%E5%8A%A1%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20CAPT%5B%22%E8%91%A3%E4%BA%8B%E4%BC%9A%E4%BF%98%E8%8E%B7%22%5D%20--%3E%20RENT%5B%22%E7%A7%9F%E9%87%91%E5%8C%85%E8%A3%85%E6%88%90%E6%BF%80%E5%8A%B1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与资本预算：用股价激励会让经理在窗口期择时发行、做高短期利润，与 Baker–Wurgler、EVA 操纵衔接。合同设计应意识到经理会优化度量。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是风险分担对激励。股东分散，经理人力财富集中于本公司，最优敏感度被保险需求压低。这与家庭欧拉无关，是合同。凸性薪酬改变项目风险选择，把代理成本从偷懒转到赌大——债务契约与董事会要一起管。",-1)),(r(),t(l,null,{default:e(()=>[A(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20OPT%5B%22%E7%BB%99%E7%BB%8F%E7%90%86%E8%99%9A%E5%80%BC%E6%9C%9F%E6%9D%83%22%5D%20--%3E%20CONV%5B%22%E8%96%AA%E9%85%AC%E5%8F%98%E5%87%B8%EF%BC%9A%E4%B8%8B%E8%A1%8C%E5%B0%81%E9%A1%B6%E3%80%81%E4%B8%8A%E8%A1%8C%E4%B8%8D%E5%B0%81%E9%A1%B6%22%5D%0A%20%20CONV%20--%3E%20SAFE%5B%22%E9%80%89%E5%AE%89%E7%A8%B3%E9%A1%B9%E7%9B%AE%EF%BC%9A%E6%9C%9F%E6%9D%83%E5%A4%A7%E6%A6%82%E7%8E%87%E4%BD%9C%E5%BA%9F%22%5D%0A%20%20CONV%20--%3E%20GAMBLE%5B%22%E9%80%89%E9%AB%98%E9%A3%8E%E9%99%A9%E9%A1%B9%E7%9B%AE%EF%BC%9A%E4%B8%87%E4%B8%80%E7%BF%BB%E7%9B%98%E6%9C%9F%E6%9D%83%E5%80%BC%E9%92%B1%22%5D%0A%20%20GAMBLE%20--%3E%20SHIFT%5B%22%E8%B5%84%E4%BA%A7%E6%9B%BF%E4%BB%A3%EF%BC%9A%E8%82%A1%E4%B8%9C%E4%B8%8E%E7%BB%8F%E7%90%86%E5%88%86%E4%BA%AB%E4%B8%8A%E8%A1%8C%22%5D%0A%20%20DEBT%5B%22%E5%85%AC%E5%8F%B8%E8%83%8C%E7%9D%80%E5%80%BA%E5%8A%A1%22%5D%20--%3E%20SHIFT%0A%20%20SHIFT%20--%3E%20CRED%5B%22%E5%80%BA%E6%9D%83%E4%BA%BA%E6%9B%BF%E4%BB%96%E4%BB%AC%E6%8B%85%E4%B8%8B%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">凸性可以这样想象：普通工资像「干多少拿多少」的直线，期权像一张彩票——股价没涨过行权价就作废（损失有限），涨过头就翻倍地值钱。所以拿着期权的经理天然偏爱「要么大赢要么大输」的项目，哪怕债权人不想他这么赌。</span></p><p><span class="marginnote">Jensen–Murphy 估计的敏感度常被写成「每 1000 美元股东财富变动，CEO 财富只变动约 3.25 美元」。听起来激励弱得离谱，但要记住分母：一家大公司市值变动几十亿美元，乘上 0.325% 也是几百万美元的个人得失——低比例不等于没刺激，只是被风险厌恶压到了保险与激励的平衡点。</span></p><p>宏观与市场：牛市期权自动值钱，像择时转移。索引行权价是补丁，实务少用，因为董事会与经理都不喜欢解释。</p><h3 id="不要把「向股东看齐」写成越多股票越好" tabindex="-1">不要把「向股东看齐」写成越多股票越好 <a class="header-anchor" href="#不要把「向股东看齐」写成越多股票越好" aria-label="Permalink to &quot;不要把「向股东看齐」写成越多股票越好&quot;">​</a></h3><p>经理若已持有大量股权，再加期权可能过度风险。若持股是壕沟（投票权），激励与控制权混在一起——双层股权课再拆。Bebchuk–Fried 的抽租与 Holmström 的最优合同是对同一观测的两种读法：识别在最后一课。</p><p><span class="marginnote">Jensen–Murphy <em>JPE</em> 1990。后续薪酬水平上升，敏感度也变，但抽租争论未关闭。机制课要的是合同结构，不是 CEO 薪酬排行。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成税法对期权的处理。下一课股东激进主义：当董事会与薪酬都失灵，外部股东直接施压。接管是更极端的替换。</p><p>后课默认：薪酬是有噪音度量下的激励–保险权衡；低敏感度可以是最优。多任务与凸性会扭曲项目风险。俘获是另一候选。</p><p>主干道德风险课已给一阶；本课只接到 CEO 合同与治理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优薪酬连充足统计信号，被风险厌恶与有限责任压低敏感度。</li><li>多任务与期权凸性扭曲努力方向与风险；可以像资产替代。</li><li>低激励或高薪酬有两读：最优合同或董事会抽租。</li><li>出处：Holmström 1979；Jensen and Murphy, <em>JPE</em> 1990；Tirole。</li></ul>',12))])}const T=s(d,[["render",m]]);export{f as __pageData,T as default};
